import './draft-style.css';
import {validateDraftContent,getDraftSourceLink} from './draft-content.js';
import {newDraft,draftPhase,draftHand,draftReflectionOptions,draftReflectionText,pickDraftCard,redrawDraft,draftTotals,draftOutcome,answerDraft,nextDraftScenario,loadDraft,saveDraft} from './draft-engine.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const freshSeed=()=>{try{return crypto.getRandomValues(new Uint32Array(1))[0]||1}catch{return Date.now()%4294967295||1}};
const assetUrl=v=>typeof v==='string'?v:typeof v?.url==='string'?v.url:'';
const safeAsset=v=>{const url=assetUrl(v);return /^(?:\/(?!\/)|https:\/\/)/.test(url)?url:''};
export function mountDraft(container,{pack:input,assets={},onExit=()=>{},onLibrary=()=>{}}={}){
 const pack=validateDraftContent(input);let store;try{store=window.localStorage}catch{store={getItem(){throw Error('storage')},setItem(){throw Error('storage')}}}
 const restored=loadDraft(store,pack,freshSeed());let state=restored.state,notice=restored.notice,modal=null,focusReturn=null,alive=true;
 const art=(key,alt,cls='')=>{const src=safeAsset(assets.cards?.[key]);return src?`<img class="${cls}" src="${esc(src)}" alt="${esc(alt)}" draggable="false">`:`<div class="tp-art-unavailable ${cls}" role="img" aria-label="Illustration unavailable"><span>Illustration unavailable</span></div>`};
 const button=(name,action,extra='',cls='')=>`<button type="button" class="tp-button ${cls}" data-tp-action="${action}" ${extra}>${name}</button>`;
 const evidence=refs=>refs.map(id=>{const s=pack.sources.find(x=>x.id===id),url=getDraftSourceLink(s);return `<blockquote><p>${esc(s.excerpt)}</p><footer>${url?`<a href="${url}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`:esc(s.title)}<br><span>${esc(s.locator)}</span></footer></blockquote>`}).join('');
 const metricRow=(values,requirements=null)=>`<div class="tp-metrics">${pack.metrics.map((m,i)=>`<div><span>${esc(m.label)}</span><strong>${values[i]}${requirements&&requirements[i]?`<small> / ${requirements[i]}</small>`:''}</strong>${requirements&&requirements[i]?`<span class="tp-check ${values[i]>=requirements[i]?'is-met':''}">${values[i]>=requirements[i]?'Met':`Need ${requirements[i]-values[i]}`}</span>`:''}</div>`).join('')}</div>`;
 const lineup=()=>`<section class="tp-lineup" aria-label="Your five choices">${pack.roles.map((r,i)=>{const c=pack.cards.find(c=>c.id===state.picks[i]);return `<div class="tp-slot ${c?'is-filled':i===state.picks.length?'is-current':''}"><span class="tp-role-label">${esc(r.label)}</span>${c?`${button(`${art(c.asset,'')}<span>${esc(c.title)}</span>`,'card',`data-id="${c.id}" aria-label="Read ${esc(c.title)}"`,'tp-picked-card')}`:`<span class="tp-empty-slot" aria-label="${esc(r.label)}: empty">${i===state.picks.length?'Your next choice':'+'}</span>`}</div>`}).join('')}</section>`;
 function draftView(){const round=state.picks.length,role=pack.roles[round],cards=draftHand(pack,state),future=pack.scenarios[Math.min(round,3)];return `<div class="tp-drafting"><div class="tp-hand-area"><div class="tp-round-heading"><div><p class="tp-step">Choose ${esc(role.label.toLowerCase())}</p><h2 tabindex="-1" data-tp-heading>${esc(role.prompt)}</h2></div>${button(state.redrawRound<0?'Redraw · 1 left':'Redraw used','redraw',state.redrawRound<0?'':'disabled','tp-redraw')}</div><p class="tp-redraw-help">One redraw brings in the unseen card. Your other two options remain.</p><div class="tp-hand" aria-label="Choose one card">${cards.map((c,i)=>`<article class="tp-card" style="--deal:${i}"><h3>${esc(c.title)}</h3>${art(c.asset,`Illustration for ${c.title}`,'tp-card-art')}<p class="tp-card-description">${esc(c.description)}</p>${metricRow(c.scores)}<div class="tp-card-actions">${button('Evidence & trade-off','card',`data-id="${c.id}"`,'tp-evidence-button')}${button('Choose','pick',`data-id="${c.id}" aria-label="Choose ${esc(c.title)}"`,'tp-primary')}</div></article>`).join('')}</div></div><aside class="tp-next"><p>One challenge ahead</p>${art(future.asset,'','tp-next-art')}<h3>${esc(future.title)}</h3><p>${esc(future.prompt)}</p><div class="tp-requirements">${future.requirements.map((n,i)=>n?`<span>${esc(pack.metrics[i].label)} ${n}</span>`:'').join('')}</div><p class="tp-game-note">Capability tokens are fictional game values. Evidence explains the real ideas.</p></aside></div>`}
 function scenarioView(){const index=state.scenarioIndex,s=pack.scenarios[index],outcome=draftOutcome(pack,state,index),attempts=state.reflections[index],settled=attempts.includes(s.solution),wrong=attempts.length&&!settled;return `<section class="tp-scenario"><div class="tp-scenario-picture">${art(s.asset,`Illustration for ${s.title}`)}<span class="tp-result-seal ${outcome.passed?'is-met':''}">${outcome.passed?'Plan holds':'A gap appears'}</span></div><div class="tp-scenario-body"><p class="tp-step">Challenge ${index+1} of 4</p><h2 tabindex="-1" data-tp-heading>${esc(s.title)}</h2><p>${esc(s.prompt)}</p>${metricRow(outcome.totals,s.requirements)}<p class="tp-rule-explanation">${outcome.passed?'Your five choices meet this scenario’s game requirements.':'Your draft falls short of one or more game requirements. You can still investigate the idea and finish the story.'}</p><fieldset class="tp-reflection"><legend>${esc(s.question)}</legend>${draftReflectionOptions(pack,state,index).map(({text:o,canonicalIndex:i},displayIndex)=>`<button type="button" data-tp-action="answer" data-answer="${i}" class="tp-answer ${attempts.includes(i)?i===s.solution?'is-correct':'is-tried':''}" ${settled||attempts.includes(i)?'disabled':''}><span>${String.fromCharCode(65+displayIndex)}</span>${esc(o)}</button>`).join('')}</fieldset>${settled?`<div class="tp-feedback is-correct" role="status"><strong>Connection made</strong><p>${esc(draftReflectionText(pack,state,s.explanation,index))}</p></div>`:wrong?`<div class="tp-feedback" role="status"><strong>Look again</strong><p>${esc(draftReflectionText(pack,state,s.feedback,index))}</p></div>`:''}<div class="tp-scenario-actions">${button('Read the evidence','scenario-evidence',`data-index="${index}"`,'tp-evidence-button')}${settled?button(index===3?'See your story':'Next challenge','next','','tp-primary'):''}</div><p class="tp-game-note">Draft outcomes and learning attempts are recorded separately.</p></div></section>`}
 function completeView(){const wins=pack.scenarios.filter((_,i)=>draftOutcome(pack,state,i).passed).length,first=state.reflections.filter((a,i)=>a[0]===pack.scenarios[i].solution).length;return `<section class="tp-ending"><div class="tp-ending-head"><p class="tp-step">The story your choices made</p><h2 tabindex="-1" data-tp-heading>${esc(pack.title)}</h2><p>${esc(pack.ending)}</p></div><div class="tp-scoreboard"><div><strong>${wins}<span> / 4</span></strong><p>Scenario requirements met</p></div><div><strong>4</strong><p>Connections explored</p></div></div><p class="tp-learning-record">${first} reflection${first===1?'':'s'} answered on the first attempt; ${4-first} revisited with feedback. This records this run, not a measure of mastery.</p><div class="tp-outcomes">${pack.scenarios.map((s,i)=>{const o=draftOutcome(pack,state,i);return `<article>${art(s.asset,'')}<div><h3>${esc(s.title)}</h3><p class="${o.passed?'tp-success':'tp-gap'}">${o.passed?'Your plan met the requirements':'Your plan had a capability gap'}</p><p>${esc(draftReflectionText(pack,state,s.explanation,i))}</p>${button('Read evidence','scenario-evidence',`data-index="${i}"`,'tp-evidence-button')}</div></article>`}).join('')}</div><div class="tp-replay"><h3>What would you change?</h3><p>Try the same hand again to compare a different choice, or deal a new seed.</p>${button('Replay this seed','replay','','tp-primary')}${button('Deal a new draft','new')}${button('Choose another subject','exit')}</div></section>`}
 function modalView(){if(!modal)return '';let contents='';if(modal.kind==='card'){const c=pack.cards.find(c=>c.id===modal.id);contents=`<h2 id="tp-dialog-title">${esc(c.title)}</h2><p>${esc(c.description)}</p>${metricRow(c.scores)}<p class="tp-tradeoff">${esc(c.tradeoff)}</p><p class="tp-game-note">These tokens are authored game rules. They are not values reported by the source.</p>${evidence(c.sourceRefs)}`}
 else if(modal.kind==='source'){const s=pack.scenarios[modal.index];contents=`<h2 id="tp-dialog-title">Evidence: ${esc(s.title)}</h2>${evidence(s.sourceRefs)}`}
 else if(modal.kind==='restart'){contents=`<h2 id="tp-dialog-title">Deal a new draft?</h2><p>This starts a new run for this subject. The current draft will be replaced on this device.</p><label for="tp-seed-input">Draft seed</label><input id="tp-seed-input" type="number" min="1" max="4294967295" step="1" value="${modal.seed}"><p class="tp-game-note">Use the same seed and subject version to compare the same choices.</p>${modal.error?`<p role="alert">${esc(modal.error)}</p>`:''}${button('Start this seed','confirm-restart','','tp-primary')}`}
 else contents=`<h2 id="tp-dialog-title">How Turning Points works</h2><ol><li>Draft one card for each of five roles.</li><li>Compare the three capability tokens and read the evidence.</li><li>Use your one redraw to see the unused card for a role.</li><li>Test your completed draft against four scenarios.</li><li>Explore the explanation, then replay with a different balance.</li></ol><p>Every run can be completed. Scenario success uses fictional game thresholds; reflections explore source-supported ideas. There is no timer.</p>`;
 return `<div class="tp-modal-shade"><section class="tp-modal" role="dialog" aria-modal="true" aria-labelledby="tp-dialog-title">${button('Close','close','','tp-modal-close')}${contents}</section></div>`}
 function render(focus=false){if(!alive)return;const phase=draftPhase(state);container.dataset.phase=phase;container.dataset.round=String(phase==='draft'?state.picks.length+1:state.scenarioIndex+1);container.dataset.completed=String(phase==='complete');container.innerHTML=`<div class="tp-game tp-phase-${phase}"><header class="tp-header"><div><h1>Turning Points</h1><p>${esc(pack.title)}</p></div><div class="tp-progress">${phase==='draft'?`Draft ${state.picks.length+1} of 5`:phase==='scenario'?`Challenge ${state.scenarioIndex+1} of 4`:'Your story is complete'}</div><nav aria-label="Game navigation">${button('How to play','help')}${button('Resource library','library')}${button('Leave table','exit')}</nav></header><details class="tp-brief"><summary>${esc(pack.subtitle)}</summary><p>${esc(pack.hook)}</p></details>${phase==='draft'?draftView():phase==='scenario'?scenarioView():completeView()}${lineup()}<footer class="tp-table-footer"><p>Seed <b>${state.seed}</b> <span>·</span> Revision ${pack.revision}</p>${button('Change seed','seed')}${phase!=='draft'?metricRow(draftTotals(pack,state)):''}<p class="tp-save-status" role="status">${esc(notice||'Progress is saved on this device.')}</p></footer>${modalView()}</div>`;
 const table=safeAsset(assets.tables?.draft);if(table){const game=container.querySelector('.tp-game');game.style.backgroundImage=`linear-gradient(#172e3dbf,#172e3de8),url(${JSON.stringify(table)})`;game.style.backgroundSize='cover';game.style.backgroundAttachment='fixed'}
 if(modal)container.querySelector('.tp-modal-close')?.focus();else if(focus)container.querySelector('[data-tp-heading]')?.focus();
 }
 function commit(next,focus=true){state=next;notice=saveDraft(store,pack,state);render(focus)}
 function open(value,trigger){focusReturn=trigger?.dataset?.tpAction==='card'?`[data-tp-action="card"][data-id="${trigger.dataset.id}"]`:trigger?.dataset?.tpAction?`[data-tp-action="${trigger.dataset.tpAction}"]${trigger.dataset.index!==undefined?`[data-index="${trigger.dataset.index}"]`:''}`:null;modal=value;render()}
 function close(){modal=null;render();if(focusReturn)container.querySelector(focusReturn)?.focus()}
 function click(event){const b=event.target.closest('[data-tp-action]');if(!b||!container.contains(b)||b.disabled)return;const action=b.dataset.tpAction;
 try{if(action==='pick')commit(pickDraftCard(pack,state,b.dataset.id));else if(action==='redraw'){const next=redrawDraft(pack,state);state=next;notice=saveDraft(store,pack,state)||'One new card has joined the hand; two options remain.';render(true)}else if(action==='answer'){commit(answerDraft(pack,state,Number(b.dataset.answer)),false);const feedback=container.querySelector('.tp-feedback');feedback?.setAttribute('tabindex','-1');feedback?.focus()}else if(action==='next')commit(nextDraftScenario(pack,state));else if(action==='card')open({kind:'card',id:b.dataset.id},b);else if(action==='scenario-evidence')open({kind:'source',index:Number(b.dataset.index)},b);else if(action==='close')close();else if(action==='help')open({kind:'help'},b);else if(action==='exit')onExit();else if(action==='library')onLibrary();else if(action==='seed'||action==='new')open({kind:'restart',seed:freshSeed()},b);else if(action==='replay')open({kind:'restart',seed:state.seed},b);else if(action==='confirm-restart'){const input=container.querySelector('#tp-seed-input'),seed=Number(input.value);if(!Number.isInteger(seed)||seed<1||seed>4294967295){modal.error='Use a whole number from 1 to 4294967295.';modal.seed=input.value;render();return}modal=null;commit(newDraft(pack,seed))}}catch(e){notice=e.message;render()}}
 function keydown(event){if(!modal)return;const dialog=container.querySelector('.tp-modal');if(event.key==='Escape'){event.preventDefault();close();return}if(event.key==='Tab'){const items=[...dialog.querySelectorAll('button:not(:disabled),input,a[href]')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}}
 container.addEventListener('click',click);container.addEventListener('keydown',keydown);render();container.ownerDocument.defaultView?.scrollTo({top:0,left:0,behavior:'instant'});return {destroy(){alive=false;container.removeEventListener('click',click);container.removeEventListener('keydown',keydown);container.innerHTML='';delete container.dataset.phase;delete container.dataset.round;delete container.dataset.completed}};
}
