import {validateChapterContent} from '../chapter-content.js';
import {validateAdventureContent} from './adventure-content.js';
import {validateTownContent} from './town-content.js';
import {GOALS,BUILDINGS} from './town-engine.js';
import {validateDraftContent} from './draft-content.js';
export const GAME_TEMPLATES=[{id:'town-v1',name:'Town & business simulation',description:'Build a connected town, manage costs and services, and inspect consequences.'},{id:'underlight-v1',name:'3D RPG chapter',description:'A party adventure with three learning mechanisms.'},{id:'adventure-v1',name:'2D adventure',description:'Explore, collect, repair and follow the evidence.'},{id:'draft-v1',name:'Subject draft',description:'Make five choices, then discover their consequences.'}];
export function validatePlayableContent(raw){if(typeof raw==='string'){if(new TextEncoder().encode(raw).length>131072)throw Error('Game files must be below 128 KB.');raw=JSON.parse(raw)}const validator={'underlight-v1':validateChapterContent,'adventure-v1':validateAdventureContent,'draft-v1':validateDraftContent,'town-v1':validateTownContent}[raw?.template];if(!GAME_TEMPLATES.some(t=>t.id===raw?.template)||typeof validator!=='function')throw Error('Choose a supported Mosaic game format.');return validator(raw)}
const label=s=>s.replace(/([a-z])([A-Z])/g,'$1 $2').replace(/^./,x=>x.toUpperCase());
export function gameReviewHTML(content,esc){
 const refs=ids=>`<details class="review-evidence"><summary>Check supporting sources</summary>${ids.map(id=>{const source=content.sources.find(s=>s.id===id);return source?`<blockquote>${esc(source.excerpt)}<footer>${esc(source.title)} — ${esc(source.locator)}</footer></blockquote>`:''}).join('')}</details>`;
 const leaf=(key,value)=>{if(key==='sourceRefs')return refs(value);if(['id','topicId','schemaVersion','template','revision','sources','asset','icon','art','image'].includes(key))return '';if(value===null||value===undefined)return '';if(typeof value!=='object')return `<p><b>${esc(label(key))}:</b> ${esc(String(value))}</p>`;if(Array.isArray(value)&&value.every(v=>typeof v!=='object'))return `<p><b>${esc(label(key))}:</b> ${esc(value.join(' → '))}</p>`;return `<details class="review-group"><summary>${esc(label(key))}${Array.isArray(value)?` (${value.length})`:''}</summary>${Object.entries(value).map(([k,v])=>{if(typeof v==='object'&&v!==null)return `<section class="draft-mechanism"><h4>${esc(v.title||v.name||v.label||label(k))}</h4>${Object.entries(v).map(([a,b])=>leaf(a,b)).join('')}</section>`;return leaf(k,v)}).join('')}</details>`};
 const expected=content.template==='town-v1'?`<section class="draft-mechanism"><h3>Fixed simulation rules</h3><p>Twelve months, eight building types, four council events. ${esc(content.focus)} goals. Model prose cannot change costs, effects, road connections, production, demand or service ranges. Review whether all names and explanations match these rules. All numbers are fictional.</p><p>Goals: ${Object.entries(GOALS[content.focus]).map(([k,v])=>esc(k)+' ≥ '+v).join(', ')}.</p>${Object.entries(BUILDINGS).map(([k,b])=>`<p><b>${esc(b.name)} · build ${b.cost}, upkeep ${b.upkeep}</b>: ${esc(b.rule)}</p>`).join('')}<p>Council effects in order: promotion (spend 12 for +4 demand next month or no change); upkeep (spend 8 for +5 nature or lose 5); rain (spend 10 for +6 nature or lose 6); training (spend 12 for +4 permanent services or no change).</p></section>`:content.template==='adventure-v1'?`<section class="draft-mechanism"><h3>Expected route</h3><p>${esc(content.sequence.solution.map(i=>content.sequence.steps[i]).join(' → '))}</p></section>`:`<section class="draft-mechanism"><h3>Reflection answers</h3>${content.scenarios.map(s=>`<p><b>${esc(s.title)}:</b> ${esc(s.options[s.solution])}</p>`).join('')}</section>`;
 return `${expected}<p class="workshop-notice">Review the narrative, every expected solution, game values and evidence. Game scores describe this fictional scenario, not a measurement of mastery.</p>${Object.entries(content).filter(([k])=>!['title','hook'].includes(k)).map(([k,v])=>leaf(k,v)).join('')}<details class="review-group"><summary>All source passages</summary>${content.sources.map(s=>`<blockquote>${esc(s.excerpt)}<footer>${esc(s.title)} — ${esc(s.locator)}</footer></blockquote>`).join('')}</details>`;
}
